const GRANULAR_SETS=[];
;const state=loadState(); let current={setId:'skull-bones',index:0,mode:'cards',revealed:false,session:null,options:null,order:[]};
function defaults(){return{betaAccepted:false,cardStats:{},customSets:[],sessions:[],profile:{notifications:true,autoRepeat:true,dailyGoal:20},theme:'system'}}
function loadState(){let r={};try{r=JSON.parse(localStorage.getItem('aq_state')||'{}');if(!r||typeof r!=='object'||Array.isArray(r))r={}}catch{};const d=defaults();const s={...d,...r,profile:{...d.profile,...(r.profile||{})},cardStats:r.cardStats||{},customSets:Array.isArray(r.customSets)?r.customSets:[],sessions:Array.isArray(r.sessions)?r.sessions:[]};s.cardStats=migrateStats(s.cardStats);return s}
function save(){try{localStorage.setItem('aq_state',JSON.stringify(state));document.getElementById('storageError')?.remove();return true}catch(error){if(!document.getElementById('storageError')){const banner=document.createElement('div');banner.id='storageError';banner.className='storage-error';banner.setAttribute('role','alert');banner.textContent='Не удалось сохранить данные на устройстве. Скачайте резервную копию в настройках перед закрытием приложения.';document.body.prepend(banner)}return false}}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))} function now(){return Date.now()} function days(n){return n*86400000} function pct(a,b){return b?Math.round(a/b*100):0}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(window.__t);window.__t=setTimeout(()=>t.classList.remove('show'),2200)}
