function makeProfessionalSets(){
  const sourceByTopic={};
  GRANULAR_SETS.forEach(s=>s.cards.forEach(c=>{if(c.topicKey&&!sourceByTopic[c.topicKey])sourceByTopic[c.topicKey]=c;}));
  const sourceSetForTopic={};
  GRANULAR_SETS.forEach(s=>s.cards.forEach(c=>{if(c.topicKey&&!sourceSetForTopic[c.topicKey])sourceSetForTopic[c.topicKey]=s;}));
  const sets=[];
  PROFESSIONAL_GROUPS.forEach(g=>{
    const cards=[]; g.topics.forEach(t=>{const src=sourceSetForTopic[t]; if(src)cards.push(...src.cards.filter(c=>c.topicKey===t));});
    sets.push({id:g.id,title:g.title,subject:'Анатомия',description:g.desc,tags:['анатомия','системный набор',...g.topics],cards,cover:g.cover,collection:'professional'});
  });
  Object.keys(sourceByTopic).forEach((topic,i)=>{
    const src=sourceSetForTopic[topic];
    const cards=src.cards.filter(c=>c.topicKey===topic);
    const id='topic-'+i+'-'+slug(topic);
    sets.push({id,title:`Анатомия · ${topic}`,subject:'Анатомия',description:`Глубокий набор по теме: ${topic}. Все основные карточки темы собраны отдельно.`,tags:['анатомия','детальный набор',topic],cards,cover:PROFESSIONAL_COVERS[topic],collection:'topic'});
  });
  return sets;
}
function slug(s){return String(s).toLowerCase().replace(/ё/g,'e').replace(/[^a-z0-9а-я]+/gi,'-').replace(/^-|-$/g,'');}
const PROFESSIONAL_SETS=makeProfessionalSets();







