function getSet(id){return [window.__aq35Temp,window.__aq37Temp].find(s=>s?.id===id)||allSets().find(x=>x.id===id)}

function aqCoverSvg(s){
 const map={general:['#4776E6','#8E54E9','＋','Общие основы'],joints:['#2E86AB','#56CCF2','◇','Суставы'],muscles:['#7F53AC','#647DEE','↗','Мышцы'],digestive:['#D97757','#F6C85F','◉','Пищеварение'],respiratory:['#2E9CCA','#67D5C7','⌁','Дыхание'],heart:['#D94F70','#8E5CCB','♥','Сердце и сосуды'],lymph:['#3AAFA9','#7BD389','✦','Лимфа'],urinary:['#3B82F6','#8B5CF6','⌁','Мочевая система'],reproductive:['#C05B8F','#7C5AC8','♀♂','Половая система'],endocrine:['#6D5ACF','#D05AA4','✦','Эндокринная система'],brain:['#5B67D8','#8E5DE7','☼','Нервная система'],senses:['#3E8ED0','#8C65D6','◉','Органы чувств'],visual:['#0F766E','#38BDF8','▧','Визуальная анатомия']};
 const [a,b,sym,label]=map[s.coverKey]||map.general;
 const escSvg=v=>String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 330"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs><rect width="720" height="330" rx="34" fill="url(#g)"/><circle cx="610" cy="70" r="150" fill="#fff" opacity=".08"/><circle cx="120" cy="310" r="130" fill="#fff" opacity=".06"/><path d="M60 245 C170 150 240 300 350 190 S540 70 660 145" fill="none" stroke="#fff" stroke-opacity=".12" stroke-width="3"/><text x="52" y="88" fill="#fff" font-family="Arial,sans-serif" font-size="22" font-weight="700" opacity=".78">ALMAZOVQWIZ · АНАТОМИЯ</text><text x="52" y="185" fill="#fff" font-family="Arial,sans-serif" font-size="62" font-weight="800">${escSvg(sym)}</text><text x="52" y="242" fill="#fff" font-family="Arial,sans-serif" font-size="31" font-weight="800">${escSvg(label)}</text><text x="52" y="278" fill="#fff" font-family="Arial,sans-serif" font-size="15" opacity=".78">СТРУКТУРА · ТОПОГРАФИЯ · ФУНКЦИЯ · ПРАКТИКА</text></svg>`;
 return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)));
}
function coverMarkup(s){return `<div class="set-cover set-cover-art"><img src="${aqCoverSvg(s)}" alt="${esc(s.title)}" loading="lazy"><span class="cover-shade"></span></div>`}





