function aqNormalizeAnswer(v){return String(v||'').toLowerCase().replace(/[«»“”"'().,;:!?]/g,' ').replace(/\s+/g,' ').trim()}
function makeOptions(s,c){
 const a=aqNormalizeAnswer(c.a), candidates=s.cards.filter(x=>x.id!==c.id&&x.a&&aqNormalizeAnswer(x.a)!==a);
 const scored=candidates.map(x=>{let score=0;if(x.topicKey===c.topicKey)score+=2;if(x.difficulty===c.difficulty)score+=1;if(x.kind===c.kind)score+=1;return {x,score}}).sort((u,v)=>v.score-u.score||Math.random()-.5);
 const out=[];for(const z of scored){const val=aqNormalizeAnswer(z.x.a);if(!out.some(o=>aqNormalizeAnswer(o)===val)){out.push(z.x.a)}if(out.length===3)break}
 return [c.a,...out].sort(()=>Math.random()-.5);
}




