function saveNewSet(){
 const title=document.getElementById('newTitle')?.value.trim(),subject=document.getElementById('newSubject')?.value,desc=document.getElementById('newDesc')?.value.trim();
 const cards=[...document.querySelectorAll('#editorCards .card-editor')].map((x,i)=>{const q=x.querySelector('.eq').value.trim(),a=x.querySelector('.ea').value.trim();return {id:'custom-'+Date.now()+'-'+i,q,a,kind:'basic',tags:['пользовательская'],source:null}}).filter(x=>x.q&&x.a);
 if(!title||!cards.length){toast('Укажите название и заполните хотя бы одну карточку');return}
 const invalid=cards.find(c=>aqNormalizeAnswer(c.q).includes(aqNormalizeAnswer(c.a))&&aqNormalizeAnswer(c.a).length>3);
 if(invalid){toast('Вопрос не должен содержать ответ целиком. Переформулируйте карточку.');return}
 state.customSets.unshift({id:'set-'+Date.now(),title,subject,description:desc||'Пользовательский набор',tags:['пользовательский'],cards});save();toast('Набор создан');showView('sets');
}

