function aqRichExplanation(c){
 const blocks=[];
 if(c.explanation)blocks.push(`<div class="explain-block"><b>Почему это правильно</b><p>${esc(c.explanation)}</p></div>`);
 if(c.why)blocks.push(`<div class="explain-block"><b>Как запомнить и связать</b><p>${esc(c.why)}</p></div>`);
 if(c.clinical)blocks.push(`<div class="explain-block clinical"><b>Практический смысл</b><p>${esc(c.clinical)}</p></div>`);
 if(c.source)blocks.push(`<div class="card-source">${icon('book')}<span>${esc(c.source.name)} · ${esc(c.source.chapterTitle||'раздел')}<br><small>Точная цитата и страница не указываются до загрузки файла соответствующего тома.</small></span></div>`);
 return blocks.length?`<div class="rich-explanation">${blocks.join('')}</div>`:'';
}
