function openModeSheet(){
 const modes=[['learn','Изучение','Разбор структуры и объяснения перед активным воспроизведением'],['cards','Карточки','Интервальное повторение с оценкой «снова / сложно / хорошо / легко»'],['test','Тест','До 30 вопросов; варианты ответа; баланс тем и формулировок'],['exam','Экзамен','До 50 вопросов; минимальные подсказки; итоговая статистика'],['write','Написание','Введи термин или ответ самостоятельно']];
 document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop mode-sheet-backdrop" onclick="if(event.target===this)closeModeSheet()"><div class="mode-sheet"><div class="mode-sheet-head"><div><span class="eyebrow">РЕЖИМ ЗАНЯТИЯ</span><h2>Что тренируем сегодня?</h2><p>Режим меняет не только внешний вид, но и способ извлечения знаний.</p></div><button class="icon-btn" onclick="closeModeSheet()">×</button></div><div class="mode-grid">${modes.map(([id,t,d])=>`<button class="mode-card ${current.mode===id?'active':''}" onclick="closeModeSheet();switchMode('${id}')"><span class="mode-icon">${icon(modeIcon(id))}</span><span><b>${t}</b><small>${d}</small></span></button>`).join('')}</div></div></div>`;hydrateIcons();
}
function buildOrder(s,mode){
 const pool=[...s.cards];
 const target=mode==='exam'?Math.min(50,pool.length):mode==='test'?Math.min(30,pool.length):pool.length;
 const remaining=[...pool],out=[]; let lastTopic='',lastKind='',lastAnswer='',lastSkill='';
 while(remaining.length&&out.length<target){
  let cand=remaining.filter(c=>(c.topicKey||'')!==lastTopic); if(!cand.length)cand=[...remaining];
  let diverse=cand.filter(c=>(c.kind||'basic')!==lastKind && aqNormalizeAnswer(c.a)!==aqNormalizeAnswer(lastAnswer) && (c.skill||'')!==lastSkill);
  if(!diverse.length) diverse=cand.filter(c=>aqNormalizeAnswer(c.a)!==aqNormalizeAnswer(lastAnswer));
  if(!diverse.length) diverse=cand;
  diverse.sort(()=>Math.random()-.5);
  const pick=diverse[0]; out.push(pick); remaining.splice(remaining.indexOf(pick),1);
  lastTopic=pick.topicKey||'';lastKind=pick.kind||'';lastAnswer=pick.a;lastSkill=pick.skill||'';
 }
 return out;
}


/* ===== ALMAZOVQWIZ 3.5 · SMART REVIEW ===== */
const AQ35_VERSION='3.5.0';
const aq35BaseAllSets=allSets;
allSets=function(){return aq35BaseAllSets();};
function aq35Pool(){
  return uniqueCards().map(({c,s})=>({c,s,st:stat(c.id)}));
}
function aq35ReviewCards(limit=20){
  const rows=aq35Pool();
  const due=rows.filter(x=>x.st.seen && x.st.dueAt<=now());
  const wrong=rows.filter(x=>(x.st.wrong||0)>0).sort((a,b)=>(b.st.wrong-a.st.wrong));
  const fresh=rows.filter(x=>!x.st.seen);
  const seen=new Set(),out=[];
  [...due,...wrong,...fresh].forEach(x=>{if(out.length>=limit||seen.has(x.c.id))return;seen.add(x.c.id);out.push(x);});
  return out.slice(0,limit);
}
function aq35StartReview(limit=20){
  const rows=aq35ReviewCards(limit);
  if(!rows.length){toast('Сейчас нет карточек для умного повторения');return;}
  const temp={id:'aq35-smart-review',title:'Умное повторение · слабые места',subject:'Анатомия',description:'Автоматически собранные карточки: просроченные → ошибочные → новые.',cards:rows.map(x=>x.c),tags:['умное повторение']};
  finishSession();window.__aq35Temp=temp;
  const oldOpen=window.openStudy;
  current={setId:temp.id,index:0,mode:'cards',revealed:false,options:null,order:buildOrder(temp,'cards'),history:[],session:{answers:0,correct:0,mode:'cards',date:now(),total:Math.min(limit,temp.cards.length)}};
  history.replaceState({aqStudy:true},'',location.href.split('#')[0]+'#study/'+encodeURIComponent(temp.id));
  showView('study');
}
function aq35Dashboard(){
  const due=dueCards().length, weak=aq35Pool().filter(x=>x.st.wrong).length, fresh=aq35Pool().filter(x=>!x.st.seen).length;
  return `<div class="panel aq35-panel"><div class="section-head"><div><span class="eyebrow">SMART REVIEW · 3.5</span><h3>Что учить сейчас?</h3><p class="muted">Алгоритм собирает сначала просроченные карточки, затем ошибки и только потом новые.</p></div></div><div class="grid grid-3"><button class="btn primary" onclick="aq35StartReview(10)">⚡ 10 минут · ${Math.min(10,due+weak+fresh)}</button><button class="btn" onclick="aq35StartReview(20)">🎯 20 карточек</button><button class="btn" onclick="showView('analytics')">📊 Посмотреть слабые места</button></div><div class="settings-row"><span>К повторению</span><b>${due}</b></div><div class="settings-row"><span>С ошибками</span><b>${weak}</b></div><div class="settings-row"><span>Новые</span><b>${fresh}</b></div></div>`;
}
const aq35OldHome=home;
home=function(){aq35OldHome();const el=document.getElementById('view-home');if(el){el.insertAdjacentHTML('beforeend',aq35Dashboard());hydrateIcons();}};
const aq35OldSets=setsView;
setsView=function(...args){aq35OldSets(...args);const el=document.getElementById('view-sets');if(el){const box=document.createElement('div');box.className='section';box.innerHTML='<div class="panel"><span class="eyebrow">НОВОЕ</span><h3>Умное повторение</h3><p class="muted">Не нужно вручную искать ошибки — AlmazovQwiz сам собирает приоритетную тренировку.</p><button class="btn primary" onclick="aq35StartReview(20)">Запустить умное повторение</button></div>';el.appendChild(box);hydrateIcons();}};



/* ===== ALMAZOVQWIZ 3.6 · VISUAL ATLAS ===== */
const AQ36_VERSION='3.6.0';
function aq36VisualCards(){return uniqueCards().filter(({c})=>c.image)}
function aq36OpenAtlas(){
 const rows=aq36VisualCards();
 const root=document.getElementById('modalRoot');
 root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModeSheet()"><div class="modal" style="max-width:980px;width:min(980px,94vw)"><div class="section-head"><div><span class="eyebrow">VISUAL ATLAS · 3.6</span><h2>Визуальная анатомия</h2><p class="muted">Смотри на изображение → назови структуру → открой ответ.</p></div><button class="icon-btn" onclick="closeModeSheet()">×</button></div><div class="grid grid-3">${rows.map((x,i)=>`<button class="panel" style="text-align:left;cursor:pointer" onclick="aq36VisualStudy(${i})"><img src="${esc(x.c.image)}" style="width:100%;height:150px;object-fit:contain;border-radius:14px;background:var(--surface-2)" loading="lazy"><b>${esc(x.c.topicKey||x.s.title)}</b><small class="muted">${esc(x.c.q.slice(0,70))}</small></button>`).join('')}</div></div></div>`;
 hydrateIcons();
}
function aq36VisualStudy(i){
 const rows=aq36VisualCards(); const x=rows[i]; if(!x)return;
 document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" style="max-width:900px;width:min(900px,94vw)"><span class="eyebrow">ВИЗУАЛЬНАЯ КАРТОЧКА</span><h2>${esc(x.c.q)}</h2>${visualMarkup(x.c)}<div style="margin-top:14px"><button class="btn" onclick="this.nextElementSibling.hidden=false">Показать ответ</button><div hidden class="panel" style="margin-top:12px"><b>${esc(x.c.a)}</b>${x.c.explanation?`<p class="muted">${esc(x.c.explanation)}</p>`:''}</div></div><div style="margin-top:14px"><button class="btn soft" onclick="aq36VisualStudy(${(i+1)%rows.length})">Следующая</button> <button class="btn" onclick="aq36OpenAtlas()">К атласу</button></div></div></div>`;
}
function aq36AtlasButton(){return `<div class="panel"><span class="eyebrow">VISUAL ATLAS</span><h3>Анатомия глазами</h3><p class="muted">Отдельный режим для карточек с изображениями.</p><button class="btn primary" onclick="aq36OpenAtlas()">Открыть визуальный атлас</button></div>`;}
const aq36OldHome=home;
home=function(){aq36OldHome();const el=document.getElementById('view-home');if(el){el.insertAdjacentHTML('beforeend',aq36AtlasButton());hydrateIcons();}};



/* ===== ALMAZOVQWIZ 3.7 · EXAM BLUEPRINT ===== */
const AQ37_VERSION='3.7.0';
function aq37ExamSetup(setId){
 const s=getSet(setId)||allSets()[0]; if(!s)return;
 const max=Math.min(50,s.cards.length);
 document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="mode-sheet"><div class="mode-sheet-head"><div><span class="eyebrow">EXAM BLUEPRINT · 3.7</span><h2>Настройка экзамена</h2><p>Сначала выбери объём. Вопросы будут сбалансированы по темам и типам.</p></div><button class="icon-btn" onclick="closeModeSheet()">×</button></div><div class="grid grid-2">${[...new Set([10,20,30,50,max])].filter(n=>n>0&&n<=max).sort((a,b)=>a-b).map(n=>`<button class="mode-card" onclick="aq37StartExam('${s.id}',${n})"><span class="mode-icon">${n}</span><span><b>${n} вопросов</b><small>${n===10?'Короткая проверка':n===20?'Обычный экзамен':n===30?'Расширенный экзамен':'Полный экзаменационный банк'}</small></span></button>`).join('')}</div></div></div>`;
}
function aq37StartExam(setId,n){
 closeModeSheet(); const s=getSet(setId); if(!s?.cards.length)return;
  finishSession();n=Math.max(1,Math.min(50,s.cards.length,Math.floor(Number(n)||s.cards.length)));
 const pool=[...s.cards].sort(()=>Math.random()-.5); const selected=pool.slice(0,n);
 const temp={id:'aq37-exam-'+Date.now(),title:s.title+' · Экзамен '+n,subject:s.subject,description:'Экзаменационная выборка',cards:selected};
 window.__aq37Temp=temp;
 current={setId:temp.id,index:0,mode:'exam',revealed:false,options:null,order:buildOrder(temp,'exam'),history:[],session:{answers:0,correct:0,mode:'exam',date:now(),total:n}};
 history.replaceState({aqStudy:true},'',location.href.split('#')[0]+'#study/'+encodeURIComponent(temp.id)); showView('study');
}
function aq37ExamButton(setId){return `<button class="btn primary" onclick="aq37ExamSetup('${setId}')">✦ Настроить экзамен</button>`;}
const aq37OldSets=setsView;
setsView=function(...args){aq37OldSets(...args);const el=document.getElementById('view-sets');if(el){el.querySelectorAll('.set-card').forEach(card=>{const btn=card.querySelector('[onclick*="openStudy"]');if(btn){const m=btn.getAttribute('onclick').match(/openStudy\('([^']+)'/);if(m){card.insertAdjacentHTML('beforeend',aq37ExamButton(m[1]));}}});hydrateIcons();}};
const aq37OldMode=openModeSheet;
openModeSheet=function(){aq37OldMode();const root=document.getElementById('modalRoot');if(!root)return;const active=getSet(current.setId);if(active){const box=root.querySelector('.mode-sheet');if(box){const b=document.createElement('div');b.style.marginTop='14px';b.innerHTML=aq37ExamButton(active.id);box.appendChild(b);hydrateIcons();}}};
